#!/usr/bin/env python3
"""Static derivation of the smb2_get_data_area_len / smb2_calc_size arithmetic
and the smb2_write() data_buf guard, using the exact constants of the target
tree.  This is NOT a kernel build or a run of the kernel; it is a deterministic
model of the C control flow used to enumerate boundary cases for the review.
"""

SMB2_HDR = 64                 # SMB2_HEADER_STRUCTURE_SIZE
STRUCT_SIZE2_WRITE = 49       # smb2_req_struct_sizes[SMB2_WRITE]
OFFSETOF_BUFFER = SMB2_HDR + 48   # offsetof(struct smb2_write_req, Buffer)
MAX_STREAM_PROT_LEN = 0x00FFFFFF
WCO = 0                       # WriteChannelInfoOffset (attacker leaves 0)
WCL = 0                       # WriteChannelInfoLength (attacker leaves 0)


def data_area_old(data_offset, length):
    if data_offset:
        off, ln = data_offset, length
    else:
        off, ln = WCO, WCL
    if off > 4096:
        return None
    if off + ln > MAX_STREAM_PROT_LEN:
        return None
    return off, ln


def data_area_new(data_offset, length):
    if data_offset or length:
        off, ln = max(data_offset, OFFSETOF_BUFFER), length
    else:
        off, ln = 0, 0
    if off > 4096:
        return None
    if off + ln > MAX_STREAM_PROT_LEN:
        return None
    return off, ln


def calc_size(data_area):
    """Return clc_len as smb2_calc_size() computes it, or None on overlap error."""
    if data_area is None:
        return None
    off, ln = data_area
    size = SMB2_HDR + STRUCT_SIZE2_WRITE
    if ln > 0:
        if off + 1 < size:
            return None
        size = off + ln
    return size


def check_message(data_area, declared_len):
    """ksmbd_smb2_check_message: accept if clc_len == declared (or 'more padding')."""
    clc = calc_size(data_area)
    if clc is None:
        return "reject(calc)"
    if declared_len == clc or declared_len == clc + 1:
        return "accept"
    if declared_len % 8 == 0 and declared_len == (clc + 7) // 8 * 8:
        return "accept(pad)"
    if clc < declared_len:
        return "accept(padded-more, clc<len)"
    return "reject(len mismatch)"


def write_guard_old(data_offset, length, rfc1002_len_at_req, special_alias=True):
    if special_alias and data_offset == OFFSETOF_BUFFER - 4:
        return "data_buf=&Buffer[0]"
    if data_offset + length > rfc1002_len_at_req:
        return "reject(-EINVAL)"
    return "data_buf=base+%d (n=%d)" % (data_offset, data_offset + length)


def write_guard_new(data_offset, length, rfc1002_len_at_req, special_alias=True):
    if special_alias and data_offset == OFFSETOF_BUFFER - 4:
        return "data_buf=&Buffer[0]"
    if data_offset < OFFSETOF_BUFFER:
        return "reject(-EINVAL)"
    return "data_buf=base+%d (n=%d)" % (data_offset, data_offset + length)


# rfc1002 value that get_rfc1002_len(req) returns for a non-first compound PDU:
# the SMB2 ProtocolId 0xFE534D42 read as BE32 and masked with 0xffffff.
PROTOCOL_ID_AS_LEN = 0xFE534D42 & 0xFFFFFF

print("OFFSETOF_BUFFER =", OFFSETOF_BUFFER)
print("fixed write PDU size =", SMB2_HDR + STRUCT_SIZE2_WRITE)
print("get_rfc1002_len(non-first compound PDU) =", PROTOCOL_ID_AS_LEN)
print()

cases = [
    ("normal write", 112, 1000, 1112),
    ("crafted compound, clc_len as declared len", 0, 1000, 113),
    ("crafted single/compound padded to full size", 0, 1000, 1112),
    ("small offset 50, len 100, len field 212", 50, 100, 212),
    ("legacy alias offset 108, len 0, len field 113", 108, 0, 113),
]

for name, doff, length, declared in cases:
    print("case:", name, "DataOffset=%d Length=%d declared_len=%d" % (doff, length, declared))
    for label, fn in (("OLD", data_area_old), ("NEW", data_area_new)):
        da = fn(doff, length)
        print("  %s data_area=%s calc_size=%s check_message=%s"
              % (label, da, calc_size(da), check_message(da, declared)))
    print("  smb2_write guard (req points into a compound -> rfc1002_len=%d):"
          % PROTOCOL_ID_AS_LEN)
    print("    OLD:", write_guard_old(doff, length, PROTOCOL_ID_AS_LEN))
    print("    NEW:", write_guard_new(doff, length, PROTOCOL_ID_AS_LEN))
    print()

